// experimental 1.1 custom-ref feature. Accepts the JSON string "1.1" and the
// JSON number 1.1 (which decodes to float64).
func isV11Value(val any) bool {
	switch v := val.(type) {
	case string:
		return v == "1.1"
	case float64:
		return v == 1.1
	}
	return false
}

