package strategy

import (
	"context"
	"log/slog"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// mirrorMetadataToV11Ref advances the experimental 1.1 custom ref
// (refs/entire/checkpoints/v1.1) to whatever the v1 metadata branch currently
// points at, when checkpoints_version "1.1" is opted in.
//
// This is a local-only, write-only mirror: v1 remains the durable source of
// truth, nothing reads the 1.1 ref, and the push hook does not push it. The
// ref shares v1's exact commit object (one write, a second pointer), so the
// two stay byte-identical.
//
// Call this only AFTER a successful v1 committed write/update. A mirror failure
// must never affect the v1 write that preceded it, so problems here are logged,
// not returned.
func mirrorMetadataToV11Ref(ctx context.Context, repo *git.Repository) {
	if !settings.MirrorsToV11Ref(ctx) {
		return
	}

	v1Ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		// v1 metadata branch not present yet — nothing to mirror. Expected on
		// first use, so debug rather than warn.
		logging.Debug(ctx, "v1.1 mirror skipped: v1 metadata branch unavailable",
			slog.String("error", err.Error()))
		return
	}

	mirrorRefName := plumbing.ReferenceName(paths.MetadataRefName)
	if existing, err := repo.Reference(mirrorRefName, true); err == nil && existing.Hash() == v1Ref.Hash() {
		return // already in sync
	}

	if err := repo.Storer.SetReference(plumbing.NewHashReference(mirrorRefName, v1Ref.Hash())); err != nil {
		logging.Warn(ctx, "v1.1 mirror failed to update custom ref",
			slog.String("ref", paths.MetadataRefName),
			slog.String("error", err.Error()))
		return
	}

	logging.Debug(ctx, "v1.1 mirror updated custom ref",
		slog.String("ref", paths.MetadataRefName),
		slog.String("hash", v1Ref.Hash().String()))
}

