package strategy

import (
	"context"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/perf"
)

// PrePush is called by the git pre-push hook before pushing to a remote.
// It pushes the entire/checkpoints/v1 branch alongside the user's push.
// Legacy checkpoints v2 settings are ignored and warn before falling back to v1.
//
// If a checkpoint_remote is configured in settings, checkpoint branches/refs
// are pushed to the derived URL instead of the user's push remote.
//
// Configuration options (stored in .entire/settings.json under strategy_options):
//   - push_sessions: false to disable automatic pushing of checkpoints
//   - checkpoint_remote: {"provider": "github", "repo": "org/repo"} to push to a separate repo
func (s *ManualCommitStrategy) PrePush(ctx context.Context, remote string) error {
	// Load settings once for remote resolution and push_sessions check.
	// Spanned because checkpoint-remote resolution can perform a one-time
	// network fetch of the metadata branch (fetchMetadataBranchIfMissing),
	// which is otherwise invisible in the pre-push trace.
	resolveCtx, resolveSpan := perf.Start(ctx, "resolve_push_settings")
	ps := resolvePushSettings(resolveCtx, remote)
	resolveSpan.End()

	if ps.pushDisabled {
		return nil
	}

	settings.WarnIfCheckpointsV2Disallowed(ctx)

	// Thread the span's context into the push so the network push and any
	// fetch+rebase recovery nest beneath it as child steps in the perf trace.
	pushCtx, pushCheckpointsSpan := perf.Start(ctx, "push_checkpoints_branch")
	err := pushBranchIfNeeded(pushCtx, ps.pushTarget(), paths.MetadataBranchName)
	pushCheckpointsSpan.RecordError(err)
	pushCheckpointsSpan.End()

	return err
}

// TestPushBranchIfNeeded_LocalBareRepo_PushesSuccessfully verifies that
// pushBranchIfNeeded works with a local bare repo path as the target.
// This exercises the same code path that PrePush uses when pushTarget()
// returns a URL, but with a local path. It validates the core routing
// behavior: a branch can be pushed to an arbitrary target path.
//
// Not parallel: uses t.Chdir() (required for OpenRepository).
func TestPushBranchIfNeeded_LocalBareRepo_PushesSuccessfully(t *testing.T) {
	ctx := context.Background()

	tmpDir := setupRepoWithCheckpointBranch(t)

	// Create a bare repo as the push target.
	bareDir := t.TempDir()
	initCmd := exec.CommandContext(ctx, "git", "init", "--bare")
	initCmd.Dir = bareDir
	initCmd.Env = testutil.GitIsolatedEnv()
	if output, err := initCmd.CombinedOutput(); err != nil {
		t.Fatalf("git init --bare failed: %v\n%s", err, output)
	}

	t.Chdir(tmpDir)

	// Push using pushBranchIfNeeded with the bare repo path as target.
	err := pushBranchIfNeeded(ctx, bareDir, paths.MetadataBranchName)
	require.NoError(t, err, "pushBranchIfNeeded should succeed with a local bare repo target")

	// Verify the branch arrived on the bare repo.
	verifyCmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+paths.MetadataBranchName)
	verifyCmd.Dir = bareDir
	verifyCmd.Env = testutil.GitIsolatedEnv()
	if output, err := verifyCmd.CombinedOutput(); err != nil {
		t.Errorf("branch should exist on bare remote after push: %v\n%s", err, output)
	}
}

// TestFetchAndRebase_DivergedBranches verifies that when local and remote
// metadata branches have diverged (shared ancestor, different commits on each),
// fetchAndRebaseSessionsCommon produces a linear history (no merge commits)

