package strategy

import (
	"context"
	"log/slog"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// mirrorMetadataToCustomRef advances the v1 custom ref
// (refs/entire/checkpoints/v1.1) to the v1 metadata branch's current commit
// when checkpoints_version "1.1" is opted in.
//
// v1 stays the source of truth; the custom ref is a local-only mirror sharing
// v1's exact commit — nothing reads it and it is never pushed. Call only after
// a successful v1 committed write; a mirror failure must not affect that write,
// so problems are logged, not returned.
func mirrorMetadataToCustomRef(ctx context.Context, repo *git.Repository) {
	if !settings.MirrorsToCustomRef(ctx) {
		return
	}

	v1Ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		// No v1 metadata branch yet — nothing to mirror. Expected on first use.
		logging.Debug(ctx, "custom-ref mirror skipped: v1 metadata branch unavailable",
			slog.String("error", err.Error()))
		return
	}

	customRef := plumbing.ReferenceName(paths.MetadataRefName)
	if existing, err := repo.Reference(customRef, true); err == nil && existing.Hash() == v1Ref.Hash() {
		return // already in sync
	}

	if err := repo.Storer.SetReference(plumbing.NewHashReference(customRef, v1Ref.Hash())); err != nil {
		logging.Warn(ctx, "custom-ref mirror failed",
			slog.String("ref", paths.MetadataRefName),
			slog.String("error", err.Error()))
		return
	}

	logging.Debug(ctx, "custom-ref mirror updated",
		slog.String("ref", paths.MetadataRefName),
		slog.String("hash", v1Ref.Hash().String()))
}

