package strategy

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// setupCustomRefRepo creates an isolated repo with one commit, writes settings
// with the given checkpoints_version (empty string omits the option), chdirs
// in, and returns the open repo.
func setupCustomRefRepo(t *testing.T, version string) *git.Repository {
	t.Helper()
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")

	body := `{"enabled": true}`
	if version != "" {
		body = `{"enabled": true, "strategy_options": {"checkpoints_version": ` + version + `}}`
	}
	entireDir := filepath.Join(tmpDir, ".entire")
	require.NoError(t, os.MkdirAll(entireDir, 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(entireDir, "settings.json"), []byte(body), 0o644))

	t.Chdir(tmpDir)
	repo, err := git.PlainOpen(tmpDir)
	require.NoError(t, err)
	return repo
}

// setV1MetadataBranch points the v1 metadata branch at HEAD and returns the hash.
func setV1MetadataBranch(t *testing.T, repo *git.Repository) plumbing.Hash {
	t.Helper()
	head, err := repo.Head()
	require.NoError(t, err)
	require.NoError(t, repo.Storer.SetReference(
		plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), head.Hash())))
	return head.Hash()
}

func customRefHash(t *testing.T, repo *git.Repository) (plumbing.Hash, bool) {
	t.Helper()
	ref, err := repo.Reference(plumbing.ReferenceName(paths.MetadataRefName), true)
	if err != nil {
		return plumbing.ZeroHash, false
	}
	return ref.Hash(), true
}

// Not parallel: uses t.Chdir().
func TestMirrorMetadataToCustomRef_CreatesRefWhenEnabled(t *testing.T) {
	repo := setupCustomRefRepo(t, `"1.1"`)
	v1Hash := setV1MetadataBranch(t, repo)

	mirrorMetadataToCustomRef(t.Context(), repo)

	got, ok := customRefHash(t, repo)
	require.True(t, ok, "expected %s to exist", paths.MetadataRefName)
	assert.Equal(t, v1Hash, got)
}

// Not parallel: uses t.Chdir().
func TestMirrorMetadataToCustomRef_DisabledNoOp(t *testing.T) {
	repo := setupCustomRefRepo(t, "") // v1 only
	setV1MetadataBranch(t, repo)

	mirrorMetadataToCustomRef(t.Context(), repo)

	_, ok := customRefHash(t, repo)
	assert.False(t, ok, "custom ref must not be created when not opted in")
}

// Not parallel: uses t.Chdir().
func TestMirrorMetadataToCustomRef_AdvancesExistingRef(t *testing.T) {
	repo := setupCustomRefRepo(t, `"1.1"`)
	oldHash := setV1MetadataBranch(t, repo)
	require.NoError(t, repo.Storer.SetReference(
		plumbing.NewHashReference(plumbing.ReferenceName(paths.MetadataRefName), oldHash)))

	cwd, err := os.Getwd()
	require.NoError(t, err)
	testutil.WriteFile(t, cwd, "f2.txt", "more")
	testutil.GitAdd(t, cwd, "f2.txt")
	testutil.GitCommit(t, cwd, "second")
	newHash := setV1MetadataBranch(t, repo)
	require.NotEqual(t, oldHash, newHash)

	mirrorMetadataToCustomRef(t.Context(), repo)

	got, ok := customRefHash(t, repo)
	require.True(t, ok)
	assert.Equal(t, newHash, got)
}

// Not parallel: uses t.Chdir().
func TestMirrorMetadataToCustomRef_V1MissingNoOp(t *testing.T) {
	repo := setupCustomRefRepo(t, `"1.1"`) // no v1 metadata branch created

	mirrorMetadataToCustomRef(t.Context(), repo)

	_, ok := customRefHash(t, repo)
	assert.False(t, ok, "custom ref must not be created when v1 metadata branch is absent")
}

func bareHasRef(ctx context.Context, t *testing.T, dir, ref string) bool {
	t.Helper()
	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", ref)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	return cmd.Run() == nil
}

// TestPrePush_DoesNotPushCustomRef proves the phase-1 invariant: even with the
// mirror opted in and both refs present locally, pre-push pushes only the v1
// branch and never the v1 custom ref.
//
// Not parallel: uses t.Chdir().
func TestPrePush_DoesNotPushCustomRef(t *testing.T) {
	ctx := t.Context()
	repo := setupCustomRefRepo(t, `"1.1"`)
	head := setV1MetadataBranch(t, repo)
	require.NoError(t, repo.Storer.SetReference(
		plumbing.NewHashReference(plumbing.ReferenceName(paths.MetadataRefName), head)))

	cwd, err := os.Getwd()
	require.NoError(t, err)
	bareDir := t.TempDir()
	runGit := func(dir string, args ...string) {
		cmd := exec.CommandContext(ctx, "git", args...)
		cmd.Dir = dir
		cmd.Env = testutil.GitIsolatedEnv()
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v failed: %v\n%s", args, err, out)
		}
	}
	runGit(bareDir, "init", "--bare")
	runGit(cwd, "remote", "add", "origin", bareDir)

	require.NoError(t, (&ManualCommitStrategy{}).PrePush(ctx, "origin"))

	assert.True(t, bareHasRef(ctx, t, bareDir, "refs/heads/"+paths.MetadataBranchName),
		"v1 metadata branch should be pushed")
	assert.False(t, bareHasRef(ctx, t, bareDir, paths.MetadataRefName),
		"v1 custom ref must never be pushed")
}

